class Potion {
  constructor(name, quantity) {
    this.name = name;
    this.quantity = Math.max(0, quantity);
  }

  drink() {
    if (this.quantity > 0) {
      this.quantity--;
      return `You drink a generic ${this.name} Potion.`;
    } else {
      return `No ${this.name} Potion left!`;
    }
  }
}

class HealingPotion extends Potion {
  constructor(quantity, healAmount) {
    super("Healing", quantity);
    this.healAmount = healAmount;
  }

  drink() {
    if (this.quantity > 0) {
      this.quantity--;
      return `You drink a Healing Potion and restore ${this.healAmount} HP!`;
    } else {
      return "No Healing Potion left!";
    }
  }
}

class ManaPotion extends Potion {
  constructor(quantity, manaRestoreAmount) {
    super("Mana", quantity);
    this.manaRestoreAmount = manaRestoreAmount;
  }

  drink() {
    if (this.quantity > 0) {
      this.quantity--;
      return `You drink a Mana Potion and restore ${this.manaRestoreAmount} MP!`;
    } else {
      return "No Mana Potion left!";
    }
  }
}

